// emre — публичный Worker: сайт + Telegram-уведомления + Mini App AI-агента.
// Секреты задаются в Cloudflare Dashboard → Settings → Variables and Secrets:
// TELEGRAM_BOT_TOKEN, ADMIN_TOKEN, TELEGRAM_CHAT_ID, BOT_NAME

const FILES = {
  "/": { type: "text/html; charset=utf-8", b64: "" },
  "/index.html": { type: "text/html; charset=utf-8", b64: "" },
  "/styles.css": { type: "text/css; charset=utf-8", b64: "" },
  "/app.js": { type: "application/javascript; charset=utf-8", b64: "" },
  "/app": { type: "text/html; charset=utf-8", b64: "" }
};

const CORS = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Methods": "GET, POST, OPTIONS",
  "Access-Control-Allow-Headers": "content-type",
  "Cache-Control": "no-store"
};

function json(data, status = 200) {
  return new Response(JSON.stringify(data), {
    status,
    headers: { ...CORS, "Content-Type": "application/json; charset=utf-8" }
  });
}

function text(body, status = 200) {
  return new Response(body, { status, headers: { ...CORS, "Content-Type": "text/plain; charset=utf-8" } });
}

function decode(b64) {
  const bin = atob(b64);
  const bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  return new TextDecoder("utf-8").decode(bytes);
}

function esc(value) {
  return String(value ?? "")
    .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
}

async function announce(request, env, url) {
  if (url.searchParams.get("token") !== env.ADMIN_TOKEN) return text("Неверный token", 403);
  let body;
  try { body = await request.json(); } catch { return json({ error: "Некорректный JSON" }, 400); }

  const chatId = body.chat_id || env.TELEGRAM_CHAT_ID;
  if (!chatId) return json({ error: "Не указан Telegram-чат" }, 400);
  const botName = env.BOT_NAME || "emre";

  const heading = body.kind === "start" ? "🔴 <b>СТРИМ НАЧАЛСЯ!</b>" : "📢 <b>УВЕДОМЛЕНИЕ О СТРИМЕ</b>";
  const lines = [heading, ""];
  if (body.name) lines.push("👤 " + esc(body.name));
  if (body.game) lines.push("🎮 Игра: " + esc(body.game));
  if (body.title) lines.push("📝 " + esc(body.title));
  if (body.description && body.description !== body.title) lines.push("💬 " + esc(body.description));
  if (body.link) lines.push("👉 Смотреть: " + esc(body.link));
  if (body.date) {
    const d = new Date(body.date);
    if (!isNaN(d.getTime())) {
      const msk = new Date(d.getTime() + 3 * 3600 * 1000);
      const months = ["января", "февраля", "марта", "апреля", "мая", "июня", "июля", "августа", "сентября", "октября", "ноября", "декабря"];
      const p = (n) => String(n).padStart(2, "0");
      lines.push("🕒 " + msk.getUTCDate() + " " + months[msk.getUTCMonth()] + ", " + p(msk.getUTCHours()) + ":" + p(msk.getUTCMinutes()) + " МСК");
    }
  }
  const message = lines.join("\n") + "\n\n💜 " + esc(botName);

  const res = await fetch(`https://api.telegram.org/bot${env.TELEGRAM_BOT_TOKEN}/sendMessage`, {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify({ chat_id: chatId, text: message, parse_mode: "HTML" })
  });
  const data = await res.json();
  if (!data.ok) return json({ error: data.description || "Telegram error" }, 502);
  return json({ ok: true, chat_id: chatId });
}

async function chat(request, env) {
  let body;
  try { body = await request.json(); } catch { return json({ error: "Некорректный JSON" }, 400); }
  const history = Array.isArray(body.history) ? body.history.slice(-10) : [];
  const messages = [
    { role: "system", content: "Ты Емеран — дружелюбный AI-агент сайта emre. Отвечай на русском, кратко и по делу." },
    ...history.filter((m) => m && typeof m.content === "string").map((m) => ({
      role: m.role === "assistant" ? "assistant" : "user",
      content: String(m.content).slice(0, 4000)
    })),
    { role: "user", content: String(body.message || "").slice(0, 4000) }
  ];
  try {
    const res = await fetch("https://text.pollinations.ai/openai", {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify({ model: "openai", messages, stream: false, max_tokens: 500, temperature: 0.5 })
    });
    const data = await res.json();
    const answer = data.choices && data.choices[0] && data.choices[0].message && data.choices[0].message.content;
    if (!answer) throw new Error("Пустой ответ модели");
    return json({ ok: true, answer: String(answer) });
  } catch (e) {
    return json({ ok: false, error: e.message || "Ошибка модели" }, 502);
  }
}

export default {
  async fetch(request, env, ctx) {
    const url = new URL(request.url);
    if (request.method === "OPTIONS") return new Response(null, { status: 204, headers: CORS });

    if (url.pathname === "/health") {
      try {
        const res = await fetch(`https://api.telegram.org/bot${env.TELEGRAM_BOT_TOKEN}/getMe`);
        const data = await res.json();
        if (!data.ok) throw new Error(data.description || "Telegram error");
        return json({ ok: true, username: data.result.username, name: data.result.first_name });
      } catch (e) {
        return json({ ok: false, error: e.message || "Ошибка бота" }, 502);
      }
    }

    if (url.pathname === "/announce") {
      if (request.method !== "POST") return text("Only POST", 405);
      try { return await announce(request, env, url); } catch (e) { return json({ error: e.message || "Ошибка отправки" }, 502); }
    }

    if (url.pathname === "/api/chat") {
      if (request.method !== "POST") return text("Only POST", 405);
      return await chat(request, env);
    }

    if (request.method !== "GET") return text("Only GET", 405);
    const file = FILES[url.pathname];
    if (!file) return text("Not found", 404);
    return new Response(decode(file.b64), { headers: { ...CORS, "Content-Type": file.type } });
  }
};